long long modPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1)
            result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    int n, x, pos;
    cin >> n >> x >> pos;

    // Precompute factorials and inverse factorials
    vector<long long> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }
    invFact[n] = modPow(fact[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
    }

    // Simulate binary search to determine constraints
    // We need to track the range [l, r] and at each step where mid falls
    // and what constraint it imposes on a[mid] relative to x

    int l = 0, r = n - 1;
    vector<pair<int, int>> constraints; // (index, type) where type: 0 means a[index] < x, 1 means a[index] > x

    while (l <= r) {
        int mid = (l + r) / 2;
        if (mid == pos) {
            // This is the position where x is found
            break;
