        // Actually, we can just simulate the path that must be taken

        // The key insight: at each step, the algorithm takes one branch.
        // For the algorithm to find x at pos, the path must be consistent.
        // Let's trace the path that would lead to pos.

        // If we go left (a[mid] > x), then new range is [l, mid-1]
        // If we go right (a[mid] < x), then new range is [mid+1, r]

        // pos must be in the new range for the algorithm to continue searching
        if (pos < mid) {
            // pos is in [l, mid-1], so we must have taken the branch where a[mid] > x
            constraints.push_back({mid, 1}); // a[mid] > x
            r = mid - 1;
        } else if (pos > mid) {
            // pos is in [mid+1, r], so we must have taken the branch where a[mid] < x
            constraints.push_back({mid, 0}); // a[mid] < x
            l = mid + 1;
        } else {
            // pos == mid, but we already handled mid == pos above
            // This shouldn't happen in the loop
            break;
        }
    }

    // Now we have constraints on certain positions
    // Count the number of valid permutations

    // Total positions: n
    // One position is fixed: pos has value x
    // Some positions have constraints: either < x or > x
    // Remaining positions are free

    // Let's count:
    // - Number of values less than x: x - 1
    // - Number of values greater than x: n - x
