    // - Positions with constraint > x: need to be filled with values from {x+1, ..., n}
    // - Free positions: can be filled with remaining values

    int countLess = 0, countGreater = 0;
    for (auto& c : constraints) {
        if (c.second == 0) countLess++;
        else countGreater++;
    }

