    if (countLess > x - 1 || countGreater > n - x) {
        cout << 0 << endl;
        return 0;
    }

    // Number of ways:
    // 1. Choose which values go to the "less than x" constrained positions: C(x-1, countLess) * countLess!
    //    = P(x-1, countLess) = (x-1)! / (x-1-countLess)!
    // 2. Choose which values go to the "greater than x" constrained positions: P(n-x, countGreater)
    // 3. The remaining positions (free) get the remaining values: (n - 1 - countLess - countGreater)!

    // Total = P(x-1, countLess) * P(n-x, countGreater) * (n - 1 - countLess - countGreater)!
    //       = (x-1)! / (x-1-countLess)! * (n-x)! / (n-x-countGreater)! * (n-1-countLess-countGreater)!

    long long result = 1;

    // P(x-1, countLess)
    if (countLess > 0) {
        result = (result * fact[x - 1]) % MOD;
        result = (result * invFact[x - 1 - countLess]) % MOD;
    }

    // P(n-x, countGreater)
    if (countGreater > 0) {
        result = (result * fact[n - x]) % MOD;
        result = (result * invFact[n - x - countGreater]) % MOD;
    }

    // Remaining free positions
    int freeCount = n - 1 - countLess - countGreater;
    if (freeCount > 0) {
        result = (result * fact[freeCount]) % MOD;
    }

    cout << result << endl;

    return 0;
}
